// Evals for the match scorer — the model output that decides which ~189 of
// 11,370 jobs the user ever sees.
//
// These run in CI on every push and cost nothing: they read a committed golden
// fixture (lib/evals/fixtures/match-scorer.golden.json, regenerated by
// scripts/snapshot-eval-data.ts) rather than calling a model or a database.
// Deterministic by construction, so a red build here is a real regression and
// never yesterday's data moving.
//
// Two families, deliberately:
//
//   1. RANKING — does the score separate what the user acts on from what they
//      ignore? This is the question lib/strategy/proposals.ts already surfaces
//      to the user ("the current scores are not separating repliers from
//      non-repliers"). It needs behavioural labels, and right now there is
//      exactly ONE genuine application on this account, so it correctly
//      REFUSES to return a verdict. That refusal is the point: the first time
//      this was pointed at the data, 16 of 17 "applications" were demo rows
//      seeded by picking the highest-scoring jobs, and a naive version would
//      have reported near-perfect separation while measuring only how the seed
//      script was written.
//
//   2. DISTRIBUTION — is the scorer discriminating at all? Needs no labels, so
//      it is meaningful from day one over the 289 real scored jobs in the
//      fixture. A rubric that drifts into rating everything 60 is perfectly
//      useless and would pass every ranking check that never ran.

import { describe, expect, it } from 'vitest'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import {
  MIN_SAMPLE_PER_CLASS,
  evaluateRanking,
  formatEvalResult,
  rankingAuc,
  scoreSpread,
  type LabelledCase,
} from './harness'

interface Fixture {
  note: string
  excludedDemoRows: number
  cases: LabelledCase[]
}

const fixture: Fixture = JSON.parse(
  readFileSync(path.resolve(process.cwd(), 'lib/evals/fixtures/match-scorer.golden.json'), 'utf8')
)
const positives = fixture.cases.filter((c) => c.positive)
const negatives = fixture.cases.filter((c) => !c.positive)

describe('match scorer — ranking against real user behaviour', () => {
  it('reports honestly rather than grading on too little data', () => {
    const result = evaluateRanking('match-scorer ranking', fixture.cases, 0.7)

    // Printed either way: a skipped eval that says nothing is indistinguishable
    // from one that never ran.
    console.log(formatEvalResult(result))

    if (result.verdict === 'insufficient-data') {
      expect(result.score).toBeNull()
      expect(result.summary).toContain('Not enough labelled data')
      // The gate that lets this become a real assertion later, automatically.
      expect(positives.length).toBeLessThan(MIN_SAMPLE_PER_CLASS)
      return
    }

    // Once enough genuine applications exist, this becomes a hard regression
    // gate with no further code change: AUC 0.5 is a coin flip, so 0.7 is the
    // floor at which the score is carrying real signal.
    expect(result.verdict, result.summary).toBe('pass')
  })

  it('excluded the seeded demo rows from the labelled set', () => {
    // The contamination guard. If a future snapshot stops filtering, this fails
    // before anyone quotes a number built on it.
    expect(fixture.excludedDemoRows).toBeGreaterThan(0)
    expect(fixture.note).toContain('demo-seeded rows excluded')
  })

  it('AUC is computed correctly, including ties', () => {
    // Pinning the metric itself. Integer match scores collide constantly, so
    // tie handling is not an edge case here — it is most of the comparisons.
    const perfect: LabelledCase[] = [
      { id: 'a', score: 90, positive: true },
      { id: 'b', score: 10, positive: false },
    ]
    expect(rankingAuc(perfect).auc).toBe(1)

    const inverted: LabelledCase[] = [
      { id: 'a', score: 10, positive: true },
      { id: 'b', score: 90, positive: false },
    ]
    expect(rankingAuc(inverted).auc).toBe(0)

    const allTied: LabelledCase[] = [
      { id: 'a', score: 50, positive: true },
      { id: 'b', score: 50, positive: false },
    ]
    expect(rankingAuc(allTied).auc).toBe(0.5)
  })
})

describe('match scorer — is it discriminating at all', () => {
  it('does not pile every job into one band', () => {
    // No behavioural labels needed, so this is a real gate today. A scorer that
    // rates everything the same is useless and stable, which is exactly the
    // failure a ranking-only suite would sail past.
    const scores = negatives.map((c) => c.score)
    const spread = scoreSpread(scores)
    console.log(
      `[INFO] score spread ${spread.toFixed(3)} over ${scores.length} scored jobs ` +
        `(0 = all in one decile, 1 = even)`
    )
    expect(scores.length).toBeGreaterThan(50)
    expect(spread).toBeGreaterThan(0.5)
  })

  it('uses the full range rather than a narrow band', () => {
    const scores = negatives.map((c) => c.score)
    const min = Math.min(...scores)
    const max = Math.max(...scores)
    console.log(`[INFO] score range ${min}..${max}`)
    // A scorer compressed into 20 points cannot rank 11,370 jobs usefully.
    expect(max - min).toBeGreaterThan(40)
  })

  it('every score is inside the 0-100 the UI promises', () => {
    // match-badge and the score bands both assume 0-100. A score outside it
    // renders as a broken badge and silently breaks matchTone's bands.
    for (const c of fixture.cases) {
      expect(c.score, `${c.label ?? c.id} scored ${c.score}`).toBeGreaterThanOrEqual(0)
      expect(c.score, `${c.label ?? c.id} scored ${c.score}`).toBeLessThanOrEqual(100)
    }
  })
})

describe('scoreSpread', () => {
  it('is 0 when everything lands in one decile', () => {
    expect(scoreSpread([61, 62, 63, 64, 65])).toBe(0)
  })

  it('is 1 when every decile is equally populated', () => {
    const even = Array.from({ length: 10 }, (_, i) => i * 10 + 5)
    expect(scoreSpread(even)).toBeCloseTo(1, 5)
  })

  it('is 0 for no data rather than throwing', () => {
    expect(scoreSpread([])).toBe(0)
  })
})
